namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Bruschetta", Category = "appetizers", Ingredients = "Baguette\nTomatoes\nFresh basil\nGarlic\nOlive oil\nBalsamic vinegar", Steps = "1. Slice and toast the baguette.\n2. Dice tomatoes and mix with chopped basil, minced garlic, and olive oil.\n3. Spoon the tomato mixture onto toasted bread.\n4. Drizzle with balsamic vinegar and serve.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Stuffed Mushrooms", Category = "appetizers", Ingredients = "Button mushrooms\nCream cheese\nGarlic\nParmesan\nBreadcrumbs\nParsley", Steps = "1. Remove stems from mushrooms and hollow out caps.\n2. Mix cream cheese, minced garlic, parmesan, and breadcrumbs.\n3. Fill mushroom caps with the mixture.\n4. Bake at 375°F for 20 minutes until golden.", AverageRating = 4.2, RatingCount = 8 },
        new Recipe { Id = 3, Title = "Spaghetti Carbonara", Category = "main-courses", Ingredients = "Spaghetti\nPancetta\nEggs\nParmesan cheese\nBlack pepper\nGarlic", Steps = "1. Cook spaghetti until al dente.\n2. Fry pancetta until crispy.\n3. Whisk eggs with grated parmesan and pepper.\n4. Toss hot pasta with pancetta, then quickly stir in egg mixture.\n5. Serve immediately with extra parmesan.", AverageRating = 4.8, RatingCount = 25 },
        new Recipe { Id = 4, Title = "Grilled Chicken Tacos", Category = "main-courses", Ingredients = "Chicken breast\nTaco seasoning\nTortillas\nAvocado\nSalsa\nLime\nCilantro", Steps = "1. Season chicken with taco seasoning and grill until cooked through.\n2. Slice chicken into strips.\n3. Warm tortillas on the grill.\n4. Assemble tacos with chicken, sliced avocado, salsa, and cilantro.\n5. Squeeze lime over top.", AverageRating = 4.6, RatingCount = 18 },
        new Recipe { Id = 5, Title = "Chocolate Lava Cake", Category = "desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract", Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until fluffy.\n3. Fold chocolate mixture into eggs, add flour and vanilla.\n4. Pour into greased ramekins.\n5. Bake at 425°F for 12-14 minutes.\n6. Invert onto plates and serve immediately.", AverageRating = 4.9, RatingCount = 30 },
        new Recipe { Id = 6, Title = "Tiramisu", Category = "desserts", Ingredients = "Ladyfingers\nMascarpone\nEspresso\nCocoa powder\nEggs\nSugar\nMarsala wine", Steps = "1. Brew espresso and let cool; mix with Marsala.\n2. Beat egg yolks with sugar, fold in mascarpone.\n3. Whip egg whites and fold into mascarpone mixture.\n4. Dip ladyfingers in espresso and layer in dish.\n5. Spread mascarpone cream over ladyfingers.\n6. Repeat layers and dust with cocoa powder.\n7. Refrigerate for at least 4 hours.", AverageRating = 4.7, RatingCount = 22 },
        new Recipe { Id = 7, Title = "Tomato Basil Soup", Category = "soups", Ingredients = "Canned tomatoes\nFresh basil\nOnion\nGarlic\nHeavy cream\nVegetable broth", Steps = "1. Sauté diced onion and garlic until soft.\n2. Add canned tomatoes and vegetable broth.\n3. Simmer for 20 minutes.\n4. Blend until smooth.\n5. Stir in heavy cream and fresh basil.\n6. Season with salt and pepper.", AverageRating = 4.3, RatingCount = 15 },
        new Recipe { Id = 8, Title = "Berry Smoothie", Category = "beverages", Ingredients = "Mixed berries\nBanana\nGreek yogurt\nHoney\nAlmond milk", Steps = "1. Add all ingredients to a blender.\n2. Blend until smooth.\n3. Pour into a glass and enjoy.", AverageRating = 4.1, RatingCount = 10 },
        new Recipe { Id = 9, Title = "Sourdough Bread", Category = "baking", Ingredients = "Bread flour\nSourdough starter\nWater\nSalt", Steps = "1. Mix flour, starter, and water. Rest 30 minutes.\n2. Add salt and knead briefly.\n3. Stretch and fold every 30 minutes for 2 hours.\n4. Shape and place in a banneton.\n5. Cold proof overnight in refrigerator.\n6. Bake in Dutch oven at 450°F for 40 minutes.", AverageRating = 4.4, RatingCount = 20 },
    };

    private readonly Dictionary<(int recipeId, string visitorId), int> _ratings = new();

    public List<Recipe> GetByCategory(string category)
        => _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id)
        => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void RateRecipe(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
    }

    public List<string> GetCategories() => new()
    {
        "appetizers", "main-courses", "desserts", "soups", "beverages", "baking"
    };

    public string GetCategoryDisplayName(string category) => category switch
    {
        "appetizers" => "🥗 Appetizers",
        "main-courses" => "🍝 Main Courses",
        "desserts" => "🍰 Desserts",
        "soups" => "🍲 Soups",
        "beverages" => "🥤 Beverages",
        "baking" => "🍞 Baking",
        _ => category
    };
}
"}

