@page "/category/{CategorySlug}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@RecipeService.GetCategoryDisplayName(CategorySlug) - Recipe Community</PageTitle>

<h1>@RecipeService.GetCategoryDisplayName(CategorySlug)</h1>
<p><a href="/">← Back to Categories</a></p>

@if (recipes.Any())
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p class="text-muted">No recipes in this category yet. <a href="/submit">Be the first to submit one!</a></p>
}

@code {
    [Parameter] public string CategorySlug { get; set; } = string.Empty;

    private List<RecipeCommunity.Models.Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(CategorySlug);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

@if (recipe is not null)
{
    <PageTitle>@recipe.Title - Recipe Community</PageTitle>

    <h1>@recipe.Title</h1>
    <p><a href="/category/@recipe.Category">← Back to @RecipeService.GetCategoryDisplayName(recipe.Category)</a></p>

    <div class="row">
        <div class="col-md-8">
            <div class="card mb-3">
                <div class="card-body">
                    <h3>Ingredients</h3>
                    <ul>
                        @foreach (var ingredient in recipe.Ingredients.Split('\n'))
                        {
                            <li>@ingredient</li>
                        }
                    </ul>
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <h3>Instructions</h3>
                    @foreach (var step in recipe.Steps.Split('\n'))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>

        <div class="col-md-4">
            <div class="card">
                <div class="card-body text-center">
                    <h4>Rate This Recipe</h4>
                    <p class="text-muted">
                        ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                    </p>
                    <StarRating RecipeId="@recipe.Id" />
                </div>
            </div>
        </div>
    </div>
}
else
{
    <PageTitle>Recipe Not Found</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe. <a href="/">Browse categories</a></p>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (hoverRating > 0 ? hoverRating : selectedRating) ? "filled" : "")"
              @onclick="() => SubmitRating(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              role="button"
              title="@star star(s)">★</span>
    }
</div>

@if (submitted)
{
    <p class="text-success mt-2"><strong>Thanks for rating!</strong></p>
}
else
{
    <p class="text-muted mt-2">Click a star to rate</p>
}

<style>
    .star-rating .star {
        font-size: 2rem;
        color: #ccc;
        cursor: pointer;
        transition: color 0.2s;
    }
    .star-rating .star.filled {
        color: #ffc107;
    }
    .star-rating .star:hover {
        color: #ffdb4d;
    }
