toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<h1>📝 Submit Your Recipe</h1>
<p><a href="/">← Back to Home</a></p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@recipe.Title</strong>" with the community.</p>
        <a href="/recipe/@recipe.Id" class="btn btn-primary">View Your Recipe</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="ResetForm">Submit Another</button>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8">
            <EditForm Model="recipe" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger" />

                <div class="mb-3">
                    <label for="title" class="form-label">Recipe Title</label>
                    <InputText id="title" @bind-Value="recipe.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
                </div>

                <div class="mb-3">
                    <label for="category" class="form-label">Category</label>
                    <InputSelect id="category" @bind-Value="recipe.Category" class="form-select">
                        <option value="">-- Select a category --</option>
                        @foreach (var cat in RecipeService.GetCategories())
                        {
                            <option value="@cat">@RecipeService.GetCategoryDisplayName(cat)</option>
                        }
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label for="ingredients" class="form-label">Ingredients (one per line)</label>
                    <InputTextArea id="ingredients" @bind-Value="recipe.Ingredients" class="form-control" rows="6" placeholder="2 cups flour&#10;1 cup sugar&#10;3 large apples..." />
                </div>

                <div class="mb-3">
                    <label for="steps" class="form-label">Steps</label>
                    <InputTextArea id="steps" @bind-Value="recipe.Steps" class="form-control" rows="8" placeholder="1. Preheat oven to 350°F.&#10;2. Mix dry ingredients...&#10;3. ..." />
                </div>

                <button type="submit" class="btn btn-success btn-lg" disabled="@(!IsFormValid())">
                    Submit Recipe
                </button>
            </EditForm>
        </div>
    </div>
}

@code {
    private Recipe recipe = new();
    private bool submitted;

    private bool IsFormValid()
        => !string.IsNullOrWhiteSpace(recipe.Title)
        && !string.IsNullOrWhiteSpace(recipe.Category)
        && !string.IsNullOrWhiteSpace(recipe.Ingredients)
        && !string.IsNullOrWhiteSpace(recipe.Steps);

    private void HandleSubmit()
    {
        if (!IsFormValid()) return;
        RecipeService.AddRecipe(recipe);
        submitted = true;
    }

    private void ResetForm()
    {
        recipe = new Recipe();
        submitted = false;
    }
}

